define('taoTestRunnerPlugins/runner/plugins/tools/preventDropToInput',['jquery', 'lodash', 'taoTests/runner/plugin', 'util/namespace'], function ($, _, pluginFactory, namespaceHelper) {
  'use strict';
  var _defaults = {
    selector: 'input.qti-textEntryInteraction, .qti-extendedTextInteraction textarea',
    draggableSelector: 'img, image'
  };
  return pluginFactory({
    name: 'preventDropToInput',
    init: function init() {
      var self = this;
      var testRunner = self.getTestRunner();
      this.getTestRunner().after('renderitem', function renderItem() {
        var config = _.defaults(self.getConfig() || {}, _defaults);
        var $items = testRunner.getAreaBroker().getContentArea().find(config.selector);
        var disabled = {};
        $(config.draggableSelector).off('.preventdropimg').on(namespaceHelper.namespaceAll('dragstart', 'preventdropimg'), function handleDragStart(e) {
          var target = e.originalEvent.target;
          e.originalEvent.dataTransfer.setData("text/plain", target.id);
          e.originalEvent.dataTransfer.setDragImage(target, 0, 0);
          _.forEach($items, function (el, key) {
            var $el = $(el);
            disabled[key] = !!$el.prop('disabled');
            $el.prop('disabled', true);
          });
        }).on(namespaceHelper.namespaceAll('dragend', 'preventdropimg'), function handleDragEnd() {
          _.forEach($items, function (el, key) {
            var $el = $(el);
            $el.prop('disabled', disabled[key]);
          });
          disabled = {};
        });
      }).on('destroy', function destroy() {
        var config = _.defaults(self.getConfig() || {}, _defaults);
        $(config.draggableSelector).off('.preventdropimg');
      });
    }
  });
});
