define('taoTestRunnerPlugins/runner/plugins/security/sectionPause',['lodash', 'i18n', 'taoTests/runner/plugin', 'taoQtiTest/runner/helpers/map', 'taoQtiTest/runner/config/states'], function (_, __, pluginFactory, mapHelper, states) {
  'use strict';
  var sectionPauseCategory = 'x-tao-proctored-auto-pause';
  var pauseMessage = 'All students will begin the next section at the same time. Please relax quietly until the room supervisor starts the next section.';
  return pluginFactory({
    name: 'sectionPause',
    init: function init() {
      var previousSection;
      var testRunner = this.getTestRunner();
      testRunner.before('loaditem', function () {
        var context = testRunner.getTestContext();
        var map = testRunner.getTestMap();
        var section = mapHelper.getSection(map, context.sectionId);
        var item = mapHelper.getItem(map, context.itemIdentifier);
        return new Promise(function (resolve, reject) {
          if (context.options.sectionPause && previousSection && section && section.id !== previousSection.id && item && _.includes(item.categories, sectionPauseCategory)) {
            testRunner.on('leave.sectionPause', function () {
              testRunner.off('.sectionPause');
            }).before('error.sectionPause', function () {
              if (testRunner.getProxy().isOffline()) {
                testRunner.off('.sectionPause').before('pause.sectionPause', function () {
                  testRunner.trigger('leave', {
                    code: states.testSession.suspended,
                    message: pauseMessage
                  });
                  return Promise.reject();
                });
              }
            }).trigger('disableitem').trigger('pause', {
              reasons: {
                category: 'condition',
                subCategory: 'pausedSection'
              },
              message: __(pauseMessage),
              originalMessage: pauseMessage
            });
            return reject();
          }
          previousSection = section;
          return resolve();
        });
      });
    }
  });
});
